python3 -c "
import sys
try:
    lines = open('findings.md').readlines()
except FileNotFoundError:
    sys.exit(0)
in_section = False
result = []
for line in lines:
    s = line.rstrip('\n')
    if s == '## Summary':
        in_section = True
    elif in_section and s.startswith('## '):
        break
    elif in_section:
        result.append(s)
print('\n'.join(result))
"
